/*
 * A129347  Number of inequivalent n-colorings of the 5-dimensional hypercube
 *          under the set of geometric transformations generated by all
 *          possible compositions of the 5 main reflections and the 10 main
 *          rotations and their inverses, in any order, with repetition of
 *          these geometric transformations allowed.
 * https://oeis.org/A129347
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = (1184*n^4 + 1624*n^8 + 240*n^10 + 400*n^12 + 311*n^16 +
 *            60*n^20 + 20*n^24 + n^32) / 3840
 * Range:     u8 n <= 1, u16 n <= 1, u32 n <= 2, u64 n <= 5, u128 n <= 9,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    /* Use 128‑bit arithmetic to avoid overflow on 64‑bit builds. */
    unsigned __int128 nn = (unsigned __int128)n;
    unsigned __int128 n2  = nn * nn;
    unsigned __int128 n4  = n2 * n2;
    unsigned __int128 n8  = n4 * n4;
    unsigned __int128 n10 = n8 * n2;
    unsigned __int128 n12 = n8 * n4;
    unsigned __int128 n16 = n8 * n8;
    unsigned __int128 n20 = n16 * n4;
    unsigned __int128 n24 = n16 * n8;
    unsigned __int128 n32 = n16 * n16;

    unsigned __int128 sum = 0;
    sum += (unsigned __int128)1184 * n4;
    sum += (unsigned __int128)1624 * n8;
    sum += (unsigned __int128)240  * n10;
    sum += (unsigned __int128)400  * n12;
    sum += (unsigned __int128)311  * n16;
    sum += (unsigned __int128)60   * n20;
    sum += (unsigned __int128)20   * n24;
    sum += n32;

    return (seq_t)(sum / 3840);
}
